create temporary table move_q (qid bigint primary key, target text not null) on commit drop;
insert into move_q values (7, 'ai-content'), (168, 'data-analysis'), (172, 'data-analysis'), (188, 'programming'), (192, 'data-analysis'), (207, 'cyber'), (272, 'ai-at-work'), (273, 'ai-at-work'), (276, 'cyber'), (277, 'data-analysis'), (280, 'data-analysis'), (282, 'data-analysis'), (284, 'ai-at-work'), (285, 'ai-no-code'), (286, 'ai-no-code'), (287, 'data-analysis'), (291, 'ai-at-work'), (292, 'ai-at-work'), (293, 'ai-at-work'), (343, 'data-analysis'), (539, 'cyber'), (555, 'ai-content'), (563, 'data-analysis'), (569, 'cyber'), (570, 'cyber'), (571, 'data-analysis'), (582, 'data-analysis'), (585, 'cyber'), (587, 'ai-no-code'), (589, 'cyber'), (621, 'data-analysis'), (623, 'ai-at-work');

do $$
declare
  v_admin uuid := (select a.user_id from public.admins a order by a.added_at limit 1);
  v_q bigint;
  n integer;
begin
  if v_admin is null then raise exception 'no admin'; end if;
  -- לפני: כל פריט ברשימות עדיין ממתין, וקורס חדש שהקורס שלו טיוטה. אחרת מישהו כבר החליט עליו.
  select count(*) into n from (select qid from approve_q union all select qid from reject_q) x
  where not exists (select 1 from public.course_change_queue q join public.courses c on c.id = q.course_id
                    where q.id = x.qid and q.status = 'pending' and q.kind = 'new_course' and c.status = 'draft');
  if n > 0 then raise exception '% queue items are no longer pending drafts', n; end if;
  if exists (select 1 from move_q m left join public.categories t on t.slug = m.target and t.replaced_by = '{}' where t.id is null) then
    raise exception 'unknown or retired target category';
  end if;

  update public.courses c set category_id = t.id
  from move_q m join public.course_change_queue q on q.id = m.qid
  join public.categories t on t.slug = m.target
  where c.id = q.course_id and c.status = 'draft';

  for v_q in select qid from approve_q order by qid loop
    perform public.approve_course_change(v_q, v_admin);
  end loop;
  for v_q in select qid from reject_q order by qid loop
    perform public.reject_course_change(v_q, v_admin);
  end loop;

  -- 3 קורסים באתר שהתאריך שלהם עבר: טיוטה, ביומן, והדף לא נקרא יותר.
  with gone as (
    update public.courses c set status = 'draft'
    where c.id in ('a4aa16a4-f4a8-4e6a-a87e-fe1cff2ec994', '60aae23c-1645-44d8-9053-06f23a37c7fb', '7b27c465-2644-412d-bbe1-f3accd2223d3')
      and c.status <> 'draft'
    returning c.id, c.status
  ), logged as (
    insert into public.course_changes (course_id, field, old_value, new_value, source, approved_by)
    select g.id, 'status', '"active"', '"draft"', 'approved', v_admin from gone g
    returning course_id
  )
  update public.scrape_pages p set state = 'ignored' from logged l where p.course_id = l.course_id;

  -- אחרי: אין קורס פעיל בתחום שיצא משימוש, חוץ מ"ניהול פרויקטים" שכבר היה שם.
  select count(*) into n from public.courses c join public.categories cat on cat.id = c.category_id
  where c.status <> 'draft' and cat.replaced_by <> '{}';
  if n > 1 then raise exception '% live courses in a retired category', n; end if;
end $$;

commit;
